// Checks the transformations against the original Java: each saved file input-*.rec in golden/
// (randomly generated by the port: data tables, then transformations of every kind on them and on
// each other, plus some nonsense transformations that refer to missing tables) was loaded into
// the Java TableManager (with the original TransformationManager) by scripts/golden/transformations.sh,
// which saved it again (as java-*.rec, if that differs from the input, and then that again as java2-*.rec) and wrote the computed
// contents of every table (java-*.txt).  The port must save each file as Java did, and compute
// the same values, errors and error messages.
//
// With GENERATE_TRANSFORMATION_INPUTS=1, this instead generates the input files (as transformations.sh does).
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import type { ExpressionIdentifier } from "../../../src/engine/anns/Annotations.js";
import type { Column } from "../../../src/engine/data/data/Column.js";
import { Table } from "../../../src/engine/data/data/Table.js";
import type { TableManager } from "../../../src/engine/data/data/TableManager.js";
import type { Transformation } from "../../../src/engine/data/data/Transformation.js";
import { BooleanLiteral, CallExpression, ComparisonExpression, EqualExpression, IdentExpression, NotEqualExpression, NumericLiteral, type Expression } from "../../../src/engine/expressions/transformations/expression/Expressions.js";
import { FunctionList } from "../../../src/engine/functions/transformations/function/FunctionList.js";
import { ColumnId } from "../../../src/engine/identifiers/id/ColumnId.js";
import { TableId } from "../../../src/engine/identifiers/id/TableId.js";
import { HashMap } from "../../../src/engine/java/HashMap.js";
import { Decimal } from "../../../src/engine/java/JavaBigDecimal.js";
import { JavaRandom } from "../../../src/engine/java/JavaRandom.js";
import { Aggregate } from "../../../src/engine/transformations/transformations/Aggregate.js";
import { Calculate } from "../../../src/engine/transformations/transformations/Calculate.js";
import { Check } from "../../../src/engine/transformations/transformations/Check.js";
import { Concatenate } from "../../../src/engine/transformations/transformations/Concatenate.js";
import { Filter } from "../../../src/engine/transformations/transformations/Filter.js";
import { HideColumns } from "../../../src/engine/transformations/transformations/HideColumns.js";
import { Join } from "../../../src/engine/transformations/transformations/Join.js";
import { ManualEdit } from "../../../src/engine/transformations/transformations/ManualEdit.js";
import { Sort } from "../../../src/engine/transformations/transformations/Sort.js";
import { Either } from "../../../src/engine/utility-adt/utility/adt/Either.js";
import { Pair } from "../../../src/engine/utility-adt/utility/adt/Pair.js";
import { UserException } from "../../../src/engine/utility-error/error/UserException.js";
import type { Value } from "../../../src/engine/utility/utility/Value.js";
import { dumpTables } from "../../../scripts/cli/dumpTables.js";
import { GeometricDistribution, SimpleGenerationStatus, SourceOfRandomness } from "../../support/quickcheck.js";
import { DummyManager } from "../tests-functions/fixtures/DummyManager.js";
import { TTableUtil } from "../tests-tables/fixtures/TTableUtil.js";
import { GenImmediateData } from "../tests-tables/fixtures/gen/GenImmediateData.js";
import { GenNonsenseTransformation } from "../tests-tables/fixtures/gen/nonsenseTrans/GenNonsenseTransformation.js";

const DIR = fileURLToPath(new URL("./golden/", import.meta.url));
const INPUT_COUNT = 32;
// Rows shown per column in the contents:
const MAX_ROWS = 20;

function loadAndSave(src: string): Pair<string, string>
{
    const mgr = new DummyManager();
    mgr.loadAll(src, _w => {});
    return new Pair(TTableUtil.save(mgr), dumpTables(mgr, MAX_ROWS));
}

// Java shows a computed number with its scale (2.50); the port's numbers have no trailing zeros
// (docs/CONVENTIONS.md, "Numbers"):
function normalise(s: string): string
{
    return s.replace(/(\d)\.(\d*?)0+(?!\d)/g, (_m, i: string, f: string) => f === "" ? i : i + "." + f);
}

// Makes random transformations of every kind on the given tables (which can be used as sources):
class TransformationMaker
{
    private nextId = 1;

    public constructor(private readonly mgr: TableManager, private readonly r: JavaRandom)
    {
    }

    private pick<T>(items: readonly T[]): T
    {
        return items[this.r.nextInt(items.length)]!;
    }

    private details(): Table.InitialLoadDetails
    {
        return new Table.InitialLoadDetails(new TableId(("Trans " + this.nextId++) as ExpressionIdentifier), null, null, null);
    }

    private columnsOf(t: Table): readonly Column[]
    {
        try
        {
            return t.getData().getColumns();
        }
        catch (e)
        {
            if (!(e instanceof UserException))
                throw e;
            return [];
        }
    }

    private isType(c: Column, test: (typeName: string) => boolean): boolean
    {
        try
        {
            return test(c.getType().getType().toString());
        }
        catch (e)
        {
            if (!(e instanceof UserException))
                throw e;
            return false;
        }
    }

    // An expression for a new column, of some kind:
    private expression(t: Table, columns: readonly Column[]): Expression
    {
        const fl = FunctionList.getFunctionLookup(this.mgr.getUnitManager());
        const c = this.pick(columns);
        const col = IdentExpression.column(c.getName());
        switch (this.r.nextInt(9))
        {
            case 0: return col;
            case 1: return new CallExpression(fl, "to text", col);
            case 2: return new CallExpression(fl, "list length", IdentExpression.makeEntireColumnReference(t.getId(), c.getName()));
            case 3: return new EqualExpression([col, new CallExpression(fl, "element", IdentExpression.makeEntireColumnReference(t.getId(), c.getName()), new NumericLiteral(new Decimal(1), null))], false);
            case 4: return new CallExpression(fl, "abs", col);
            case 5: return new CallExpression(fl, "minimum", IdentExpression.makeEntireColumnReference(t.getId(), c.getName()));
            case 6: return new NotEqualExpression(col, IdentExpression.column(this.pick(columns).getName()));
            case 7: return new CallExpression(fl, "not", col);
            default: return IdentExpression.load("row");
        }
    }

    private condition(t: Table, columns: readonly Column[]): Expression
    {
        const fl = FunctionList.getFunctionLookup(this.mgr.getUnitManager());
        const c = this.pick(columns);
        if (this.r.nextInt(5) === 0)
            return new BooleanLiteral(this.r.nextBoolean());
        const op = this.pick(ComparisonExpression.ComparisonOperator.values());
        return new ComparisonExpression([IdentExpression.column(c.getName()), new CallExpression(fl, "element", IdentExpression.makeEntireColumnReference(t.getId(), c.getName()), new NumericLiteral(new Decimal(1 + this.r.nextInt(5)), null))], [op]);
    }

    public make(tables: readonly Table[]): Transformation | null
    {
        const src = this.pick(tables);
        const columns = this.columnsOf(src);
        if (columns.length === 0)
            return null;
        switch (this.r.nextInt(9))
        {
            case 0:
            {
                const calc = new HashMap<ColumnId, Expression>();
                for (let i = 1 + this.r.nextInt(3); i > 0; i--)
                    calc.set(this.r.nextInt(3) === 0 ? this.pick(columns).getName() : new ColumnId(("New " + i) as ExpressionIdentifier), this.expression(src, columns));
                return new Calculate(this.mgr, this.details(), src.getId(), calc);
            }
            case 1:
                return new Filter(this.mgr, this.details(), src.getId(), this.condition(src, columns));
            case 2:
                return new Sort(this.mgr, this.details(), src.getId(), Array.from({ length: 1 + this.r.nextInt(3) }, () => new Pair(this.r.nextInt(10) === 0 ? new ColumnId("Missing") : this.pick(columns).getName(), this.r.nextBoolean() ? Sort.Direction.ASCENDING : Sort.Direction.DESCENDING)));
            case 3:
            {
                const fl = FunctionList.getFunctionLookup(this.mgr.getUnitManager());
                const splitBy = Array.from({ length: this.r.nextInt(3) }, () => this.pick(columns).getName()).filter((c, i, a) => a.findIndex(x => x.equals(c)) === i);
                const summaries = Array.from({ length: this.r.nextInt(3) }, (_x, i) =>
                {
                    const c = this.pick(columns);
                    const e: Expression = this.r.nextBoolean() ? IdentExpression.load("group count") : new CallExpression(fl, this.pick(["list length", "minimum", "maximum"]), IdentExpression.column(c.getName()));
                    return new Pair(new ColumnId(("Sum " + i) as ExpressionIdentifier), e);
                });
                return new Aggregate(this.mgr, this.details(), src.getId(), summaries, splitBy);
            }
            case 4:
            {
                const other = this.pick(tables);
                const otherColumns = this.columnsOf(other);
                const pairs: Pair<ColumnId, ColumnId>[] = [];
                for (const a of columns)
                    for (const b of otherColumns)
                        if (this.r.nextInt(3) === 0 && this.isType(a, ta => this.isType(b, tb => ta === tb)))
                            pairs.push(new Pair(a.getName(), b.getName()));
                return new Join(this.mgr, this.details(), src.getId(), other.getId(), this.r.nextBoolean(), pairs.slice(0, 2));
            }
            case 5:
                return new Concatenate(this.mgr, this.details(), Array.from({ length: 1 + this.r.nextInt(3) }, () => this.pick(tables).getId()), this.pick([Concatenate.IncompleteColumnHandling.OMIT, Concatenate.IncompleteColumnHandling.DEFAULT, Concatenate.IncompleteColumnHandling.WRAPMAYBE]), this.r.nextBoolean());
            case 6:
                return new HideColumns(this.mgr, this.details(), src.getId(), columns.filter(() => this.r.nextInt(3) === 0).map(c => c.getName()).concat(this.r.nextInt(10) === 0 ? [new ColumnId("Missing")] : []));
            case 7:
            {
                let length: number;
                try
                {
                    length = src.getData().getLength();
                }
                catch (e)
                {
                    if (!(e instanceof UserException))
                        throw e;
                    return null;
                }
                if (length === 0)
                    return null;
                const keyColumn = this.r.nextInt(3) === 0 ? null : this.pick(columns);
                const replacements = HashMap.javaOrder<ColumnId, ManualEdit.ColumnReplacementValues>();
                for (let n = 1 + this.r.nextInt(2); n > 0; n--)
                {
                    const c = this.pick(columns);
                    try
                    {
                        const values: Pair<Value, Either<string, Value>>[] = [];
                        for (let i = 1 + this.r.nextInt(3); i > 0; i--)
                        {
                            const row = this.r.nextInt(length);
                            const key: Value = keyColumn === null ? new Decimal(row) : keyColumn.getType().getCollapsed(row);
                            values.push(new Pair(key, this.r.nextInt(4) === 0 ? Either.left<string, Value>("#bad " + i) : Either.right<string, Value>(c.getType().getCollapsed(this.r.nextInt(length)))));
                        }
                        replacements.set(c.getName(), new ManualEdit.ColumnReplacementValues(c.getType().getType(), values));
                    }
                    catch (e)
                    {
                        if (!(e instanceof UserException))
                            throw e;
                        // An error value; leave out that column
                    }
                }
                return new ManualEdit(this.mgr, this.details(), src.getId(), keyColumn === null ? null : new Pair(keyColumn.getName(), keyColumn.getType().getType()), [...replacements.entries()]);
            }
            default:
                return new Check(this.mgr, this.details(), src.getId(), this.pick(Check.CheckType.values()), this.condition(src, columns));
        }
    }
}

if (process.env.GENERATE_TRANSFORMATION_INPUTS === "1")
{
    test("Generate input files", () =>
    {
        mkdirSync(DIR, { recursive: true });
        for (let seed = 1; seed <= INPUT_COUNT; seed++)
        {
            const r = new JavaRandom(BigInt(seed));
            const sourceOfRandomness = new SourceOfRandomness(r);
            const gs = new SimpleGenerationStatus(new GeometricDistribution(), sourceOfRandomness, seed % 4);
            let mgr: TableManager;
            if (seed % 4 === 0)
            {
                // A nonsense transformation (which mostly refers to missing tables):
                mgr = new GenNonsenseTransformation().generate(sourceOfRandomness, gs).mgr;
            }
            else
            {
                const original = new GenImmediateData({ numTables: { minTables: 1, maxTables: 2 }, canHaveErrorValues: seed % 3 === 0 }).generate(sourceOfRandomness, gs);
                mgr = original.mgr;
                const tables: Table[] = [...original.data];
                const maker = new TransformationMaker(mgr, r);
                for (let i = 0; i < 4 + seed % 5; i++)
                {
                    const t = maker.make(tables);
                    if (t !== null)
                    {
                        mgr.record(t);
                        tables.push(t);
                    }
                }
            }
            writeFileSync(DIR + "input-" + String(seed).padStart(2, "0") + ".rec", TTableUtil.save(mgr));
        }
    }, 300_000);
}
else
{
    const inputs = readdirSync(DIR).filter(f => f.startsWith("input-")).sort();

    describe("Transformations match Java", () =>
    {
        test("There are input files", () =>
        {
            expect(inputs.length).toBe(INPUT_COUNT);
        });

        test.each(inputs)("%s", input =>
        {
            const inputSrc = readFileSync(DIR + input, "utf8");
            const javaSavedFile = DIR + input.replace("input-", "java-");
            const javaSaved = existsSync(javaSavedFile) ? readFileSync(javaSavedFile, "utf8") : inputSrc;
            const javaContents = readFileSync(DIR + input.replace("input-", "java-").replace(".rec", ".txt"), "utf8");
            const ours = loadAndSave(inputSrc);
            // The port saves the input as Java did:
            expect(ours.getFirst()).toBe(javaSaved);
            // And computes the same contents:
            expect(normalise(ours.getSecond())).toBe(normalise(javaContents));
            // The port reads the file saved by Java, and saves it as Java did (which is not always
            // unchanged: java2-*.rec, if present):
            if (javaSaved !== inputSrc)
            {
                const java2File = DIR + input.replace("input-", "java2-");
                expect(loadAndSave(javaSaved).getFirst()).toBe(existsSync(java2File) ? readFileSync(java2File, "utf8") : javaSaved);
            }
        });
    });
}
